import {hasMotion,motionSettings} from './motion.js';
import {createGifEncoder} from '../contour/gif-encode.js';
import {Renderer} from './renderer.js';
const renderer=new Renderer();let chain=Promise.resolve();
self.onmessage=({data})=>{chain=chain.then(async()=>{try{await renderer.load(data.state.source);if(data.kind==='gif'){let encoder;const fps=Math.max(1,...data.state.fragments.filter(f=>!f.deleted&&motionSettings(data.state,f).enabled).map(f=>motionSettings(data.state,f).fps)),count=hasMotion(data.state)?fps*4:1;for(let i=0;i<count;i++){const c=renderer.render({...data.state,motionTime:(i+.01)*1000/fps},data.width,data.height,data.camera,data.quality),pixels=c.getContext('2d').getImageData(0,0,c.width,c.height).data;encoder??=createGifEncoder(c.width,c.height,pixels,Math.round(100/fps));encoder.add(pixels);postMessage({id:data.id,progress:Math.round((i+1)/count*100)});}postMessage({id:data.id,blob:encoder.finish()});return;}const c=renderer.render(data.state,data.width,data.height,data.camera,data.quality);if(data.kind==='export'){const blob=await c.convertToBlob({type:'image/png'});postMessage({id:data.id,blob})}else{const bitmap=c.transferToImageBitmap();postMessage({id:data.id,bitmap},[bitmap])}}catch(error){postMessage({id:data.id,error:error.message})}})};
